INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_BRANCH_NVG_I_FUNDAMENTALISMO_COLONIALISMO_HELP', '[COLOR_NVG_FUNDAMENTALISMO]Fundamentalismo[ENDCOLOR] (vinda do Colonialismo)[NEWLINE]Fundamentalismo de cruzada: conquistar e converter terras novas.[NEWLINE][NEWLINE][COLOR_YELLOW]Presente ao adotar:[ENDCOLOR] +250 [ICON_PEACE] Fé, 2 Missionários, todo o exército ganha Guerra Santa[NEWLINE][NEWLINE][COLOR_YELLOW]Abertura:[ENDCOLOR][NEWLINE][ICON_BULLET]Cidades novas nascem com +1 de [ICON_CITIZEN] população[NEWLINE][ICON_BULLET]+10% de [ICON_PRODUCTION] produção de unidades militares[NEWLINE][NEWLINE][COLOR_YELLOW]Políticas:[ENDCOLOR][NEWLINE][ICON_BULLET]Leis Religiosas[NEWLINE][ICON_BULLET]Clero Estatal[NEWLINE][ICON_BULLET]Missões [COLOR_POSITIVE_TEXT](só do Colonialismo)[ENDCOLOR][NEWLINE][ICON_BULLET]Conversão pela Espada [COLOR_POSITIVE_TEXT](só do Colonialismo)[ENDCOLOR][NEWLINE][ICON_BULLET]Colônias da Fé [COLOR_POSITIVE_TEXT](só do Colonialismo)[ENDCOLOR][NEWLINE][NEWLINE][COLOR_YELLOW]Ao completar:[ENDCOLOR][NEWLINE][ICON_BULLET]Novas unidades nascem com +20 de experiência[NEWLINE][ICON_BULLET]+25% de experiência em combate');
