INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_HELP', '[COLOR_POSITIVE_TEXT]Fundamentalismo[ENDCOLOR][NEWLINE][ICON_BULLET]Cidades novas nascem com +1 de [ICON_CITIZEN] população[NEWLINE][ICON_BULLET]+10% de [ICON_PRODUCTION] produção de unidades militares');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_FINAL', 'Fundamentalismo completo');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_FINAL_HELP', '[COLOR_POSITIVE_TEXT]Fundamentalismo completo[ENDCOLOR][NEWLINE][ICON_BULLET]Novas unidades nascem com +20 de experiência[NEWLINE][ICON_BULLET]+25% de experiência em combate');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_1', 'Leis Religiosas');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_1_HELP', '[COLOR_POSITIVE_TEXT]Leis Religiosas[ENDCOLOR][NEWLINE][ICON_BULLET]-10% de [ICON_HAPPINESS_4] infelicidade da população');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_2', 'Clero Estatal');
