INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_3', 'Missões');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_3_HELP', '[COLOR_POSITIVE_TEXT]Missões[ENDCOLOR] (só no Fundamentalismo vindo do Colonialismo)[NEWLINE][ICON_BULLET]Ganha 2 Missionários');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_4', 'Conversão pela Espada');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_4_HELP', '[COLOR_POSITIVE_TEXT]Conversão pela Espada[ENDCOLOR] (só no Fundamentalismo vindo do Colonialismo)[NEWLINE][ICON_BULLET]Unidades militares ganham [COLOR_POSITIVE_TEXT]Guerra Santa[ENDCOLOR]: +15% de [ICON_STRENGTH] força em combate.');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_5', 'Colônias da Fé');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_POLICY_NVG_I_FUNDAMENTALISMO_COLONIALISMO_5_HELP', '[COLOR_POSITIVE_TEXT]Colônias da Fé[ENDCOLOR] (só no Fundamentalismo vindo do Colonialismo)[NEWLINE][ICON_BULLET]Ganha 1 Colono[NEWLINE][ICON_BULLET]Plantação: +1 [ICON_PEACE] Fé');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_DIZIMO_IMPERIAL_SHORT', 'Dízimo Imperial');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_DIZIMO_IMPERIAL', '+3 [ICON_GOLD] Ouro para você por cidade que segue a sua religião.');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_PAZ_DIVINA_SHORT', 'Paz Divina');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_PAZ_DIVINA', '+1 [ICON_HAPPINESS_1] felicidade para você por cidade que segue a sua religião.');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_FERVOR_SHORT', 'Fervor');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_FERVOR', 'Templos +2 [ICON_PEACE] Fé e Santuários +1 [ICON_PEACE] Fé.');
