INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_MOSTEIROS', '+2 [ICON_PRODUCTION] Produção e +1 [ICON_FOOD] Comida nas cidades seguidoras.');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_GUERRA_SANTA_SHORT', 'Guerra Santa');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_GUERRA_SANTA', '+30% de força contra cidades de outra religião, e as unidades militares do fundador ganham a promoção Guerra Santa (+15%).');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_INQUISICAO_SHORT', 'Inquisição Suprema');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_INQUISICAO', 'Missionários 50% mais baratos; quando a sua religião converte uma cidade, mais seguidores das outras religiões somem.');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_EVANGELHO_FOGO_SHORT', 'Evangelho de Fogo');
INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES ('TXT_KEY_BELIEF_NVG_EVANGELHO_FOGO', 'A religião se espalha 50% mais longe e 50% mais forte; Missionários +50% de força.');
